# Use this section to suppress warnings generated by your code:
def warn(*args, **kwargs):
    pass
import warnings
warnings.warn = warn
warnings.filterwarnings('ignore')

from ibm_watsonx_ai.foundation_models import ModelInference
from langchain.agents import AgentType
from ibm_watsonx_ai.metanames import GenTextParamsMetaNames as GenParams
from ibm_watson_machine_learning.foundation_models.extensions.langchain import WatsonxLLM
from langchain_community.utilities.sql_database import SQLDatabase
from langchain_community.agent_toolkits import create_sql_agent

model_id = 'ibm/granite-4-h-small'

parameters = {
    GenParams.MAX_NEW_TOKENS: 1024,      # maximale Länge der Antwort
    GenParams.TEMPERATURE: 0.2,          # niedrige Kreativität → stabile SQL-Abfragen
    GenParams.TOP_P: 0.95,
    GenParams.REPETITION_PENALTY: 1.2,
}

credentials = {
    "url": "https://us-south.ml.cloud.ibm.com"
}

project_id = "skills-network"

model = ModelInference(
    model_id=model_id,
    params=parameters,
    credentials=credentials,
    project_id=project_id
)

llm = WatsonxLLM(model=model)

import os

mysql_username = 'root'
mysql_password = os.environ['MYSQL_PASSWORD']  # aktuelles Passwort aus dem Terminal
mysql_host = os.environ['MYSQL_HOST']          # aktueller Host aus dem Terminal
mysql_port = '3306'
database_name = 'Chinook'

mysql_uri = f'mysql+mysqlconnector://{mysql_username}:{mysql_password}@{mysql_host}:{mysql_port}/{database_name}'
db = SQLDatabase.from_uri(mysql_uri)

agent_executor = create_sql_agent(
    llm=llm,
    db=db,
    verbose=True,
    handle_parsing_errors=True,
    agent_type=AgentType.ZERO_SHOT_REACT_DESCRIPTION
)

result = agent_executor.invoke("How many Album are there in the database?")
print(result["output"])